import os,sys,json,hashlib,base64,importlib.util,stat,time
from pathlib import Path
os.sched_setaffinity(0,{16})
base=Path("/data/hepta-hia-round2-20261104/evidence")
scripts=base/"development-delivery-scripts-v1";scripts.mkdir(exist_ok=False)
original=base64.b64decode("")
assert hashlib.sha256(original).hexdigest()=="fca0a6d43717eb84a132f03dc06c6f2fc809aee71ccfb71f814c9fac4bd6788e"
packager=scripts/"package_evidence.original.py";packager.write_bytes(original)
inputs=json.loads("[\"AGENT_ASSET_COPIES.json\",\"AOT_COMPOSITION_SOURCE_INTEGRATION.json\",\"NDU_SOURCE_INTEGRATION.json\",\"PROOF_SOURCE_INTEGRATION.json\",\"TOOLCHAIN_COPIES.json\",\"TOOLCHAIN_SMOKE.json\",\"WORKSPACE_SETUP.json\",\"cpp-swap-development-01\",\"cpp-swap-r1\",\"integration-smoke-r1\",\"native-race-development-01\",\"upstream-agent-capacity-development-r1\",\"upstream-agent-capacity-development-r2\",\"upstream-agent-development-r5\",\"upstream-agent-native-controls-r1\",\"upstream-agent-task-capture-r1\",\"upstream-agent-task-capture-r2\",\"upstream-agent-task-capture-r3\",\"upstream-agent-task-capture-r4\",\"upstream-agent-task-capture-r5\"]")
(scripts/"INPUTS.json").write_text(json.dumps(inputs,indent=2)+"\n")
spec=importlib.util.spec_from_file_location("root_delivery_packager",packager);module=importlib.util.module_from_spec(spec);spec.loader.exec_module(module)
output=base/"development-package-v1"
record=module.run(base,output,inputs,title="Round 2 completed development evidence (2026-11-05)",prefix="experiments/hia_round2_20261104/development/")
public=output/"public"
manifest=json.loads((public/"MANIFEST.json").read_text())
expected={r["path"]:r for r in manifest["members"]}
seen={}
for item in inputs:
 p=base/item
 for q in ([p] if p.is_file() else sorted(p.rglob("*"))):
  st=q.lstat()
  if stat.S_ISDIR(st.st_mode):continue
  assert stat.S_ISREG(st.st_mode) and st.st_nlink==1
  name=q.relative_to(base).as_posix();row=expected[name];raw=q.read_bytes()
  assert len(raw)==row["bytes"] and hashlib.sha256(raw).hexdigest()==row["sha256"]
  assert stat.S_IMODE(st.st_mode)==row["mode"] and st.st_mtime_ns==row["original_mtime_ns"]
  seen[name]=True
assert set(seen)==set(expected)
module.write(public/"ORIGINAL_INPUTS_UNCHANGED.json",{"checked_after_full_restore":True,"all_original_files_and_byte_hashes_unchanged":True,"all_modes_and_mtimes_unchanged":True,"exact_selected_file_inventory_unchanged":True,"files":len(seen),"scope":"Only the explicitly selected completed development tasks; no source checkout changes, model requests, evaluator reruns or benchmark reruns."})
staging=base64.b64decode("")
assert hashlib.sha256(staging).hexdigest()=="afaeb3af4d459d44a9a3c6f5485c9ea43a1f6c08afe1a0e93bfc346c93143452"
(public/"SOURCE_STAGING_READBACK.json").write_bytes(staging)
module.write(public/"SOURCE_STAGING_SCOPE.json",{"scope":"Intermediate source projection readback only; explicitly not the final accepted source or final qualification.","source_receipt_sha256":"afaeb3af4d459d44a9a3c6f5485c9ea43a1f6c08afe1a0e93bfc346c93143452","local_source_prefix":"d33d","public_projection_prefix":"766947","same_tree_prefix":"0d5a","final_acceptance_claimed":False})
module.write(public/"SCRIPT_PROVENANCE.json",{"original_packager_sha256":"fca0a6d43717eb84a132f03dc06c6f2fc809aee71ccfb71f814c9fac4bd6788e","original_packager_bytes":len(original),"original_packager_changed":False,"additional_check":"After full restore, verify the complete selected original file set, all byte hashes, ordinary modes and mtimes unchanged.","compression_cpu_affinity":sorted(os.sched_getaffinity(0)),"no_source_worktree_edits":True})
print(json.dumps({"package":str(public),"original_files":record["original_files"],"original_bytes":record["original_bytes"],"archive":record["archive"],"restore":record["restoration"],"post_restore_originals_unchanged":True},sort_keys=True))
